:host { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #1e293b; --blue: #2454d6; --muted: #626e7f; --border: #dce2ea; }
.ds-button { min-height: 44px; border: 0; border-radius: 8px; padding: 11px 18px; font-size: 14px; font-weight: 600; transition: background 160ms; }
.ds-primary { background: var(--blue); color: white; }
.ds-primary:hover { background: #1b43b3; }
:focus-visible { outline: 3px solid #497aef; }
